#include <zephyr/ztest.h>
#include <zephyr/lib/spsc_pbuf.h>
#include <errno.h>

#define BUFFER_SIZE 128
static uint8_t spsc_buffer_data[BUFFER_SIZE];
static struct spsc_pbuf_buffer spsc_buf;

static void *spsc_pbuf_setup(void)
{
    spsc_pbuf_init(&spsc_buf, spsc_buffer_data, BUFFER_SIZE);
    return NULL;
}

static void spsc_pbuf_teardown(void *data)
{
    ARG_UNUSED(data);
}

ZTEST_F(spsc_pbuf, test_0cpy)
{
    int wlen = spsc_pbuf_write(&spsc_buf, NULL, 0);
    zassert_equal(wlen, 0, "Expected 0 bytes written for 0-length write");
    int rlen = spsc_pbuf_read(&spsc_buf, NULL, 0);
    zassert_equal(rlen, 0, "Expected 0 bytes read for 0-length read");
}

ZTEST_F(spsc_pbuf, test_0cpy_corner1)
{
    int wlen = spsc_pbuf_write(&spsc_buf, NULL, 0);
    zassert_equal(wlen, 0, "Expected 0 bytes written for 0-length write");
}

ZTEST_F(spsc_pbuf, test_0cpy_corner2)
{
    int rlen = spsc_pbuf_read(&spsc_buf, NULL, 0);
    zassert_equal(rlen, 0, "Expected 0 bytes read for 0-length read");
}

ZTEST_F(spsc_pbuf, test_0cpy_discard)
{
    uint8_t data[10];
    spsc_pbuf_write(&spsc_buf, data, sizeof(data));
    int rlen = spsc_pbuf_read(&spsc_buf, NULL, sizeof(data)); /* Discard */
    zassert_equal(rlen, sizeof(data), "Expected to discard all data");
}

ZTEST_F(spsc_pbuf, test_0cpy_smaller)
{
    uint8_t data[10];
    spsc_pbuf_write(&spsc_buf, data, sizeof(data));
    int rlen = spsc_pbuf_read(&spsc_buf, NULL, sizeof(data) - 1); /* Discard smaller */
    zassert_equal(rlen, sizeof(data) - 1, "Expected to discard smaller amount");
}

ZTEST_F(spsc_pbuf, test_largest_alloc)
{
    size_t capacity = spsc_pbuf_capacity(&spsc_buf);
    uint8_t *data = k_malloc(capacity);
    zassert_not_null(data, "Failed to allocate data");
    int wlen = spsc_pbuf_write(&spsc_buf, data, capacity);
    zassert_equal(wlen, capacity, "Expected to write full capacity");
    k_free(data);
}

ZTEST_F(spsc_pbuf, test_spsc_pbuf_flags)
{
    uint8_t test_data = 0xAA;
    int wlen;

    /* Keep writing single-byte packets until the buffer is full. */
    /* spsc_pbuf_write will return -ENOMEM when it cannot fit another packet. */
    while (true) {
        wlen = spsc_pbuf_write(&spsc_buf, &test_data, 1);
        if (wlen == 1) {
            /* Successfully wrote a packet, continue filling. */
        } else if (wlen == -ENOMEM) {
            /* Buffer is now full (cannot fit even a 1-byte packet). */
            break;
        } else {
            /* Unexpected error during fill. */
            zassert_true(false, "Unexpected error during buffer fill: %d", wlen);
            return;
        }
    }

    /* The buffer should now be full. Attempt to write one more byte. */
    /* This should definitely fail with -ENOMEM. */
    wlen = spsc_pbuf_write(&spsc_buf, &test_data, 1);

    /* This is the assertion at line 76 in the original log. */
    zassert_equal(wlen, -ENOMEM, "Expected -ENOMEM when writing to a full buffer, got %d", wlen);

    /* Clean up for good measure, though fixture setup will re-init. */
    spsc_pbuf_drop_all(&spsc_buf);
}

ZTEST_SUITE(spsc_pbuf, NULL, spsc_pbuf_setup, NULL, spsc_pbuf_teardown, NULL);
